    "how_to_use": "Điền {CURRENT} với mô tả hiện tại, {CHANGE} với đề xuất thay đổi, {CONTEXT} (tuỳ chọn).",
    "disabled": false,
    "created_at": "2026-04-02T10:00:00Z",
    "updated_at": "2026-04-02T10:00:00Z"
